def try_load(p):
    print(f"\n-- trying {p} --")
    if torch is not None:
        try:
            d=torch.load(p,map_location="cpu")
            print(" torch.load type:", type(d))
            if isinstance(d,dict):
                print("  keys sample:", list(d.keys())[:10])
                if "W_fc.0" in d or ("state_dict" in d):
                    return d
            else:
                print("  tensor/list?", type(d))
            return d
        except Exception as e:
            print("  torch.load fail:", e)
    try:
        import numpy as np
        if p.endswith(".npz"):
            d=np.load(p,allow_pickle=True)
            print(" npz keys:", list(d.files)[:10])
            return {k:d[k] for k in d.files}
        elif p.endswith(".npy"):
            d=np.load(p,allow_pickle=True).item()
            print(" npy type", type(d))
            return d
    except Exception as e:
        print("  np load fail:", e)
    return None

state=None
ckpt_path=None
for p in cands[:20]:
    d=try_load(p)
    # unwrap
    if isinstance(d,dict) and "W_fc.0" not in d and "state_dict" in d:
        d=d["state_dict"]
    if isinstance(d,dict) and "W_fc.0" in d:
        state=d; ckpt_path=p; break

if state is None:
    print("\nNO state found with W_fc.0, abort diagnostics")
else:
    print(f"\nFOUND state in {ckpt_path} with {len(state)} keys")
    import math
    def to_t(x):
        if torch is not None and hasattr(x,"cpu"):
            return x.cpu().float()
        try:
            import numpy as np
            import torch
            return torch.as_tensor(np.asarray(x)).float()
        except: return None
    # percentiles + dead fractions
    for k in sorted(state.keys()):
        t=to_t(state[k])
        if t is None: continue
        f=t.flatten().float()
        qs=torch.quantile(f,torch.tensor([0.,0.01,0.05,0.25,0.5,0.75,0.95,0.99,1.]))
        print(f"{k} {tuple(t.shape)} mean {f.mean():.4f} std {f.std():.4f} min {f.min():.4f} max {f.max():.4f} | p1/5/50/95/99 {[f'{v:.4f}' for v in qs.tolist()]}")
        if k.startswith("ln"):
            for th in [0.05,0.1,0.2,0.5]:
                print(f"  frac<{th}: {float((f<th).float().mean()):.3f} frac<0: {float((f<0).float().mean()):.3f}")
        # per-neuron norms for 2D
        if t.dim()==2:
            # assume dim0 = out neurons for fc (1536,384) and? check both dims
            rn=torch.norm(t,dim=1)
            cn=torch.norm(t,dim=0)
            print(f"  rownorm mean {rn.mean():.3f} min {rn.min():.3f} max {rn.max():.3f} frac<0.5*mean {float((rn<0.5*rn.mean()).float().mean()):.3f}")
            print(f"  colnorm mean {cn.mean():.3f} min {cn.min():.3f} max {cn.max():.3f}")
    # SVD for attention + fc/proj (top singular values + eff rank)
    print("\n=== SVD ===")
    for k in ["W_q.0","W_q.3","W_k.0","W_k.3","W_v.0","W_v.3","W_o.0","W_o.3","W_fc.0","W_fc.3","W_proj.0","W_proj.3"]:
        if k not in state: continue
        t=to_t(state[k])
        try:
            s=torch.linalg.svdvals(t)
            s,_=torch.sort(s,descending=True)
            tot=s.sum().item()
            p=s/tot
            ent=-(p*torch.log(p+1e-12)).sum().item()
            erank=math.exp(ent)
            print(f"{k} {tuple(t.shape)} top5 {[f'{v:.2f}' for v in s[:5].tolist()]} sum {tot:.1f} effrank {erank:.1f} cond {float(s[0]/s[-1]):.1f} smallest5 {[f'{v:.2f}' for v in s[-5:].tolist()]}")
        except Exception as e:
            print(k,"svd fail",e)

